import {editorialContent,homeModuleLabels} from './editorial-model.mjs?v=20261117modules';
import {openImageCropper} from './image-cropper.mjs?v=20261117modules';
import {editorialEditor,imageEditor} from './admin-editors.mjs?v=20261117modules';
import {e,safeURL,safeImage,money,imageOf} from './ui.mjs?v=20261117modules';
import {validateContent,moduleTypes} from './content-validation.mjs?v=20261117modules';
const config=window.CONFORT4_FORMS,base=config.endpoint.split('/functions/')[0],endpoint=config.endpoint.replace('confort4-forms','confort4-site');
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
let session=null,state=null,draft=null,tab='home',offset=0,unsaved=false,pending=false;
try{session=JSON.parse(sessionStorage.getItem('confort4-session'));}catch{}
const labels={vender:'Vender',rentar:'Rentar',comprar:'Comprar',home:'Pantalla principal',team:'Quiénes somos',services:'Servicios',process:'Proceso',faq:'Preguntas frecuentes',posts:'Blog',checklists:'Checklists',leads:'Contactos',reviews:'Reseñas',inventory:'Propiedades',media:'Imágenes',settings:'Configuración',versions:'Versiones'};
const moduleLabels=homeModuleLabels;
function normalizedSession(data){return {...data,editor_username:data.editor_username||session?.editor_username,expires_at:data.expires_at||Math.floor(Date.now()/1000)+(data.expires_in||3600)};}
function persist(){if(session)sessionStorage.setItem('confort4-session',JSON.stringify(session));else sessionStorage.removeItem('confort4-session');}
async function auth(path,body,token,method='POST'){const res=await fetch(base+'/auth/v1/'+path,{method,headers:{apikey:config.publishableKey,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error('No pudimos validar tu acceso. Revisa los datos e intenta de nuevo.');return data;}
async function api(action,args={}){
 if(!session)throw Error('Inicia sesión.');
 if(session.expires_at*1000<Date.now()+60000){session=normalizedSession(await auth('token?grant_type=refresh_token',{refresh_token:session.refresh_token}));persist();}
 const res=await fetch(endpoint,{method:'POST',headers:{apikey:config.publishableKey,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({action,args}),signal:AbortSignal.timeout(25000)});
 const data=await res.json().catch(()=>({}));if(!res.ok){const error=Error(data.error||'No se pudo completar la operación.');error.code=data.code;throw error;}return data;
}
function status(text,error=false){const el=$('#admin-status')||$('#login-status');el.textContent=text;el.classList.toggle('is-error',error);}
function at(path){return path.split('.').reduce((v,k)=>v?.[k],draft);}
function set(path,value){if(path.split('.').some(k=>['__proto__','prototype','constructor'].includes(k)))throw Error('Campo no permitido.');const keys=path.split('.'),last=keys.pop();keys.reduce((v,k)=>v[k],draft)[last]=value;}
function collect(){ $$('[data-bind]').forEach(el=>{const value=el.dataset.number!==undefined?Number(el.value):el.type==='checkbox'?el.checked:el.dataset.lines!==undefined?el.value.split('\n').map(t=>t.trim()).filter(Boolean):el.value;set(el.dataset.bind,value);}); }
function input(path,label,options={}){const value=at(path);if(options.choices)return `<label>${e(label)}<select data-bind="${e(path)}">${Object.entries(options.choices).map(([key,text])=>`<option value="${e(key)}" ${value===key?'selected':''}>${e(text)}</option>`).join('')}</select></label>`;if(options.check)return `<label class="consent"><input type="checkbox" data-bind="${path}" ${value?'checked':''}><span>${e(label)}</span></label>`;return `<label>${e(label)}${options.area||options.lines?`<textarea rows="${options.lines?4:3}" data-bind="${path}" ${options.lines?'data-lines':''}>${e(options.lines?(value||[]).join('\n'):value)}</textarea>`:`<input data-bind="${path}" value="${e(value)}" ${options.number?'type="number" data-number min="0" max="1000000"':options.type?'type="'+options.type+'"':''}>`}</label>`;}
function image(path,label){return imageEditor(path,label,at(path),input);}
function block(title,body){return `<section class="admin-block"><h3>${e(title)}</h3>${body}</section>`;}
function editor(){
 const enhanced=editorialEditor(tab,draft,{input,block});if(enhanced!==null)return enhanced;
 if(tab==='checklists')return Object.keys(draft.checklists).map(key=>block({venta:'Vender',visita:'Visita',renta:'Renta'}[key],input('checklists.'+key,'Puntos · uno por línea',{lines:true}))).join('');
 return '';
}
function editorNavigation(){
 const buttons=keys=>keys.map(key=>`<button data-tab="${key}" ${tab===key?'aria-current="page"':''}>${e(labels[key])}</button>`).join('');
 return buttons(['home','team'])+'<div class="admin-nav-group"><span>Me interesa</span>'+buttons(['vender','rentar','comprar'])+'</div>'+buttons(['inventory','reviews','posts'])+'<div class="admin-nav-group"><span>Administración</span>'+buttons(['leads','media','settings','versions'])+'</div>';
}
function shell(){
 const opened=new Set($$('details[open]',$('#admin-panel')).map(element=>$('summary',element)?.textContent));
 $('.admin-login').hidden=true;$('#admin-panel').hidden=false;
 $('#admin-panel').innerHTML=`<div class="admin-shell"><aside class="admin-sidebar"><strong>Confort4 · equipo</strong><p>${e(session.editor_username||session.user?.user_metadata?.editor_username||'Cuenta autorizada')}<br>Rol: ${e(state.role)}</p><nav aria-label="Panel administrativo">${editorNavigation()}</nav><button class="text-button" id="logout">Cerrar sesión</button></aside><div class="admin-workspace"><header class="admin-toolbar"><div><h2>${labels[tab]}</h2><p id="revision">${unsaved?'Cambios sin guardar':'Borrador · versión '+state.revision}</p></div><div class="admin-actions"><button class="button button-outline" id="preview">Vista previa</button><button class="button button-outline" id="save">Guardar borrador</button><button class="button" id="publish" ${state.role!=='admin'?'disabled':''}>Publicar</button></div></header><p id="admin-status" role="status" aria-live="polite"></p><div id="admin-view">${editor()||'<p>Cargando…</p>'}</div></div></div>`;
 $$('details',$('#admin-panel')).forEach(element=>{if(opened.has($('summary',element)?.textContent))element.open=true;});
 loadTab().catch(error=>status(error.message,true));
}
async function loadTab(){
 const view=$('#admin-view'),requestedTab=tab;
 if(tab==='leads'||tab==='reviews'){
  const rows=await api('submissions',{kind:tab==='reviews'?'review':'contact',offset});if(tab!==requestedTab)return;
  const recordsView=tab==='reviews'?$('#received-reviews'):view;
  recordsView.innerHTML=`<div class="admin-records">${rows.length?rows.map(r=>{const p=r.payload;return `<article class="admin-record"><div class="module-heading"><h3>${e(p.name)}</h3><time>${e(new Date(r.created_at).toLocaleString('es-MX'))}</time></div><p>${e(p.email)} · ${e(p.phone||'Sin teléfono')}</p><p><strong>${e(p.interest)}</strong> · Aviso por correo: ${e(r.email_status)}</p><p class="record-message">${e(p.message)}</p>${p.project?`<dl>${Object.entries(p.project).filter(([,v])=>v).map(([k,v])=>`<dt>${e({zone:'Zona',property_type:'Tipo',budget:'Presupuesto',timeframe:'Plazo',contact_preference:'Contacto preferido',property_id:'Propiedad',page:'Página'}[k]||k)}</dt><dd>${e(v)}</dd>`).join('')}</dl>`:''}${tab==='leads'?`<label>Seguimiento<select data-followup="${e(r.id)}" ${state.role!=='admin'?'disabled':''}>${Object.entries({new:'Nuevo',contacted:'Contactado',in_progress:'En proceso',closed:'Cerrado',archived:'Archivado'}).map(([v,l])=>`<option value="${v}" ${r.followup===v?'selected':''}>${l}</option>`).join('')}</select></label>`:`<p>Calificación: ${e(p.rating)}/5 · Publicación autorizada: ${p.publishConsent?'Sí':'No'} · Estado: ${e(r.moderation_status)}</p><label class="consent"><input type="checkbox" data-review-visible="${e(r.id)}" ${r.moderation_status==='approved'?'checked':''} ${!p.publishConsent||state.role!=='admin'?'disabled':''}>Mostrar reseña en la página</label>${!p.publishConsent?'<small>Sin permiso de publicación. No se puede aprobar.</small>':''}`}</article>`;}).join(''):'<p>Todavía no hay registros en esta página.</p>'}</div><div class="admin-actions"><button class="text-button" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>Anteriores</button><span>Registros ${offset+1}–${offset+rows.length}</span><button class="text-button" data-offset="${offset+50}" ${rows.length<50?'disabled':''}>Siguientes</button></div>`;
 }
 if(tab==='inventory'){
  view.innerHTML='<section class="admin-block"><h3>Mis propiedades</h3><p>Todas tus propiedades activas de KW Premier aparecen automáticamente. Puedes añadir hasta 10 propiedades extra del catálogo KW; sus fichas mostrarán los datos de contacto de Confort4.</p><div id="catalog-current">Cargando…</div><button type="button" class="button" id="add-properties">Agregar más propiedades</button><details id="extra-picker" class="editor-module"><summary>Buscar propiedades extra</summary><div><form method="post" id="kw-property-link"><label>Enlace de la propiedad en KW<input name="url" type="url" maxlength="2048" placeholder="https://confort4.kw.com/es-419/property/…" required></label><button class="button button-outline">Buscar por enlace</button></form><form method="post" id="inventory-search"><label>O buscar en el catálogo conectado<input name="query" type="search" maxlength="100" placeholder="Título, colonia, municipio o asesor"></label><button class="button button-outline">Buscar propiedades</button></form><div id="inventory-results"></div></div></details></section><section class="admin-block"><h3>Mi historial</h3><p>Operaciones cargadas manualmente y las propiedades que dejen de estar activas. Puedes cambiar su estado y decidir si aparecen en el carrusel.</p><div id="history-results"></div></section>';
  const [history,catalog]=await Promise.all([api('history'),api('catalog')]);if(tab!==requestedTab)return;renderHistory(history);renderCatalog(catalog);
 }
 if(tab==='media')view.innerHTML=block('Fotos del sitio','<p>Para cambiar una foto, abre el apartado de la página y utiliza Subir foto. Ahí puedes recortar y encuadrar antes de guardar.</p>');
 if(tab==='settings')view.innerHTML=block('Recepción de formularios',`<p>Dirección actual: <strong>${e(state.settings.notification_email)}</strong>. Los envíos de prueba permanecen en Dani hasta que se cambie aquí.</p><form method="post" id="settings-form"><label>Correo que recibirá los avisos<input name="email" type="email" required value="${e(state.settings.notification_email)}"></label><button class="button" ${state.role!=='admin'?'disabled':''}>Guardar destinatario</button></form><p>Inventario automático: ID KW ${e(state.settings.inventory_advisor_id)}.</p>`);
 if(tab==='versions')view.innerHTML=block('Publicaciones anteriores',`<p>Restaurar recupera una versión en el borrador. Revísala antes de publicarla.</p>${state.versions.length?state.versions.map(v=>`<div class="version-row"><span>Versión ${e(v.id)} · ${e(new Date(v.created_at).toLocaleString('es-MX'))}</span><button class="text-button" data-restore="${e(v.id)}">Restaurar en borrador</button></div>`).join(''):'<p>El historial aparecerá después de la primera publicación desde el panel.</p>'}`);
}
function catalogRecord(p){return `<article class="admin-record catalog-record"><img src="${safeImage(imageOf(p),'thumb')}" alt="" width="160" height="100" loading="lazy"><div><h4>${e(p.titulo)}</h4><p>${e([p.colonia,p.municipio].filter(Boolean).join(' · '))}</p><p>${e(money(p.precio,p.moneda))} · ${e(p.operacion)}</p><details class="property-media-preview"><summary>Fotos de la propiedad · ${(p.imagenes||[]).length}</summary>${(p.imagenes||[]).length>1?`<div class="admin-property-photos">${p.imagenes.map(photo=>`<img src="${safeImage(typeof photo==='string'?photo:photo.url,'thumb')}" alt="" loading="lazy">`).join('')}</div>`:''}<button type="button" class="text-button" data-load-media="${e(p.id)}">Cargar o actualizar todas las fotos</button></details>${p.inactive?'<p>Ya no está activa: no aparece en el catálogo público.</p>':''}${p.own?'<p>Automática · propiedad del equipo</p>':`<label class="consent"><input type="checkbox" data-selection="${e(p.id)}" ${p.selected?'checked':''} ${state.role!=='admin'?'disabled':''}>Mostrar como propiedad extra</label>`}</div></article>`;}
function renderCatalog(rows){const own=rows.filter(p=>p.own),extra=rows.filter(p=>!p.own);$('#catalog-current').innerHTML=`<h4>Catálogo automático · ${own.length}</h4>${own.map(catalogRecord).join('')}<h4>Propiedades extra · ${extra.length}/10</h4>${extra.map(catalogRecord).join('')||'<p>No has seleccionado propiedades extra.</p>'}`;}
function renderPicker(rows){$('#inventory-results').innerHTML=rows.length?rows.map(catalogRecord).join(''):'<p>No encontramos una propiedad activa con esos datos en el inventario conectado. Puedes buscarla por título, colonia o asesor. No se agregan propiedades sin verificar.</p>';}
function renderHistory(rows){
 const container=$('#history-results');if(!container)return;
 const labels={vendida:'Vendida',rentada:'Rentada',cancelada:'Cancelada',fuera_del_mercado:'Fuera del mercado',expirada:'Expirada'};
 container.innerHTML=rows.length?rows.map(row=>`<article class="admin-record" data-history-record="${e(row.property_id)}"><img src="${e(row.photo||'assets/property-placeholder.svg')}" alt="" width="160" height="100" loading="lazy" style="object-fit:cover"><h3>${e(row.title)}</h3><p>${e(row.location)} · ${e(labels[row.status]||row.status)} · ${row.visible??!row.cancelled?'Visible en el carrusel':'Oculta del carrusel'}</p>${row.currently_active?'<p>Actualmente activa: no aparece en el carrusel de historial.</p>':''}<label>Estado<select data-history-status ${state.role!=='admin'?'disabled':''}>${Object.entries(labels).map(([value,label])=>`<option value="${value}" ${row.status===value?'selected':''}>${label}</option>`).join('')}</select></label><label><input type="checkbox" data-history-visible ${(row.visible??!row.cancelled)?'checked':''} ${state.role!=='admin'?'disabled':''}> Mostrar en el carrusel</label><button type="button" class="button button-outline" data-history="${e(row.property_id)}" ${state.role!=='admin'?'disabled':''}>Guardar estado y visibilidad</button></article>`).join(''):'<p>Todavía no hay operaciones en el historial.</p>';
}
async function bootstrap(){state=await api('bootstrap');draft=editorialContent(state.draft);unsaved=false;shell();}
async function save(){collect();validateContent(draft);const result=await api('save',{content:draft,revision:state.revision});state.revision=result.revision;unsaved=false;$('#revision').textContent='Borrador guardado · versión '+state.revision;status('Borrador guardado. Los cambios todavía no son públicos.');}
async function withPending(fn){if(pending)return;pending=true;$('#admin-panel').setAttribute('aria-busy','true');try{await fn();}catch(error){status(error.message,true);}finally{pending=false;$('#admin-panel').removeAttribute('aria-busy');}}
document.addEventListener('input',ev=>{if(ev.target.matches('[data-bind]')){unsaved=true;$('#revision').textContent='Cambios sin guardar';}});
$('#admin-panel').addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;
 if(b.dataset.tab){collect();tab=b.dataset.tab;offset=0;shell();return;}
 if(b.id==='logout'){withPending(async()=>{await fetch(base+'/auth/v1/logout?scope=local',{method:'POST',headers:{apikey:config.publishableKey,Authorization:'Bearer '+session.access_token}}).catch(()=>{});session=null;persist();localStorage.removeItem('confort4-preview');location.reload();});return;}
 if(b.id==='save')withPending(save);
 if(b.dataset.loadMedia)withPending(async()=>{status('Cargando la galería completa desde KW…');const result=await api('property_media',{id:b.dataset.loadMedia,refresh:true}),container=b.closest('details');container.querySelector('.admin-property-photos')?.remove();const track=document.createElement('div');track.className='admin-property-photos';track.innerHTML=result.images.map(url=>`<img src="${safeImage(url,'thumb')}" alt="" loading="lazy">`).join('');container.insertBefore(track,b);container.querySelector('summary').textContent='Fotos de la propiedad · '+result.images.length;status(result.images.length+' fotos cargadas.');});
 if(b.id==='add-properties'){$('#extra-picker').open=true;$('#kw-property-link input').focus();}
 if(b.dataset.postMove!==undefined){collect();const i=Number(b.dataset.postMove),j=i+Number(b.dataset.dir);if(j>=0&&j<draft.posts.length)[draft.posts[i],draft.posts[j]]=[draft.posts[j],draft.posts[i]];unsaved=true;shell();}
 for(const [add,remove,pattern,value] of [
  ['addQuestion','deleteQuestion',/^services\.\d+\.faq$/,{category:'Proceso',question:'Nueva pregunta',answer:'',visible:true}],
  ['addRow','deleteRow',/^services\.\d+\.comparison\.rows$/,['Nuevo tema','','']],
  ['addReading','deleteReading',/^services\.\d+\.sections$/,{title:'Nuevo punto',text:'',visible:true}]
 ]){const path=b.dataset[add]||b.dataset[remove];if(path&&pattern.test(path)){collect();const rows=at(path);if(b.dataset[add]){if(rows.length>=20){status('Puedes agregar hasta 20 elementos en este módulo.',true);return;}rows.push(structuredClone(value));}else rows.splice(Number(b.dataset.index),1);unsaved=true;shell();return;}}
 if(b.id==='preview'){collect();try{validateContent(draft);localStorage.setItem('confort4-preview',JSON.stringify(draft));const route={team:'quienes-somos',vender:'vender',rentar:'rentar',comprar:'comprar',inventory:'propiedades',reviews:'resena',services:'vender',posts:'blog',checklists:'recursos',faq:'preguntas'}[tab]||'index';window.open(route+'.html?preview=1','_blank','noopener');status('Vista previa abierta. No se ha publicado.');}catch(error){status(error.message,true);}}
 if(b.id==='publish')withPending(async()=>{await save();if(!window.confirm('¿Publicar este borrador de Confort4? Los visitantes verán los cambios al recargar.'))return;const result=await api('publish',{revision:state.revision});state.revision=result.revision;const latest=await api('bootstrap');state.versions=latest.versions;$('#revision').textContent='Publicado · versión '+state.revision;status('Publicado. La página pública ya puede leer esta versión.');});
 if(b.dataset.move!==undefined){collect();const id=b.dataset.move,i=draft.home.modules.indexOf(id),direction=Number(b.dataset.dir),j=i+direction;if(i<0||![-1,1].includes(direction)||j<0||j>=draft.home.modules.length)return;[draft.home.modules[i],draft.home.modules[j]]=[draft.home.modules[j],draft.home.modules[i]];unsaved=true;shell();const row=$('[data-home-sort="'+id+'"]');row?.querySelector('[data-dir="'+direction+'"]:not([disabled])')?.focus({preventScroll:true});status('Módulo movido a la posición '+(j+1)+'. Pulsa Publicar para mostrar este orden en el inicio.');return;}
 if(b.dataset.removeModule){collect();draft.home.modules=draft.home.modules.filter(m=>m!==b.dataset.removeModule);unsaved=true;shell();}
 if(b.hasAttribute('data-new-post')){collect();draft.posts.unshift({slug:'nuevo-articulo-'+Date.now(),title:'Nuevo artículo',category:'Guías',excerpt:'',cover:'assets/home-detail.jpg',author:'Equipo Confort4',updated:new Date().toISOString().slice(0,10),published:false,summary:[],sections:[{title:'Primera sección',text:''}],source:{label:'',url:''}});unsaved=true;shell();const newest=$('.admin-post');newest.open=true;newest.scrollIntoView({block:'start',behavior:'smooth'});}
 if(b.dataset.deletePost!==undefined&&window.confirm('¿Eliminar este artículo del borrador?')){collect();draft.posts.splice(Number(b.dataset.deletePost),1);unsaved=true;shell();}
 if(b.dataset.newSection!==undefined){collect();draft.posts[Number(b.dataset.newSection)].sections.push({title:'Nueva sección',text:''});unsaved=true;shell();}
 if(b.dataset.deleteSection!==undefined){collect();const [i,j]=b.dataset.deleteSection.split(',').map(Number);draft.posts[i].sections.splice(j,1);unsaved=true;shell();}
 if(b.hasAttribute('data-new-faq')){collect();draft.faq.push({category:'Proceso',question:'Nueva pregunta',answer:'',visible:true});unsaved=true;shell();}
 if(b.dataset.deleteFaq!==undefined){collect();draft.faq.splice(Number(b.dataset.deleteFaq),1);unsaved=true;shell();}
 if(b.dataset.cropPath)withPending(()=>cropAndUpload(b.dataset.cropPath));
 if(b.dataset.addPhoto){collect();const limits={'clients.items':20,'team.gallery':8,'team.nationalAward.photos':2},path=b.dataset.addPhoto;if(!limits[path])return;const rows=at(path);if(rows.length>=limits[path]){status('Has alcanzado el límite de fotos.',true);return;}rows.push(path==='clients.items'?{id:crypto.randomUUID(),photo:'',alt:'',caption:'',published:true}:{photo:'',caption:''});unsaved=true;shell();}
 if(b.dataset.deletePhoto){collect();if(!['clients.items','team.gallery','team.nationalAward.photos'].includes(b.dataset.deletePhoto))return;at(b.dataset.deletePhoto).splice(Number(b.dataset.index),1);unsaved=true;shell();}
 if(b.dataset.moderate)withPending(async()=>{await api('moderate',{id:b.dataset.moderate,status:b.dataset.status});await loadTab();status('Estado de reseña actualizado.');});
 if(b.dataset.history)withPending(async()=>{const record=b.closest('[data-history-record]');const visible=record.querySelector('[data-history-visible]').checked;renderHistory(await api('history',{id:b.dataset.history,status:record.querySelector('[data-history-status]').value,visible}));status(visible?'Estado guardado: operación visible en el carrusel.':'Estado guardado: operación oculta del carrusel.');});
 if(b.dataset.offset!==undefined){offset=Number(b.dataset.offset);loadTab().catch(error=>status(error.message,true));}
 if(b.dataset.restore)withPending(async()=>{if(!window.confirm('¿Reemplazar el borrador por esta versión anterior?'))return;await api('restore',{id:b.dataset.restore,revision:state.revision});await bootstrap();status('Versión restaurada en borrador. Aún no se ha publicado.');});
});
$('#admin-panel').addEventListener('change',ev=>{const el=ev.target;if(el.id==='add-module'&&el.value){collect();if(!moduleTypes.includes(el.value)||draft.home.modules.includes(el.value))return;draft.home.modules.push(el.value);draft.home.hiddenModules=draft.home.hiddenModules.filter(id=>id!==el.value);if(el.value==='transactions')draft.transactions.visible=true;unsaved=true;shell();status('Módulo agregado al final. Puedes subirlo y publicar el nuevo orden.');}if(el.dataset.moduleVisible){collect();draft.home.hiddenModules=draft.home.hiddenModules.filter(id=>id!==el.dataset.moduleVisible);if(!el.checked)draft.home.hiddenModules.push(el.dataset.moduleVisible);else if(el.dataset.moduleVisible==='transactions')draft.transactions.visible=true;const badge=$('[data-home-editor="'+el.dataset.moduleVisible+'"] summary span');if(badge)badge.textContent=el.checked?'Visible':'Oculto';status('Visibilidad actualizada en el borrador. Pulsa Publicar para aplicar el cambio.');unsaved=true;$('#revision').textContent='Cambios sin guardar';}if(el.dataset.teamVisible){collect();draft.team.hiddenSections=draft.team.hiddenSections.filter(id=>id!==el.dataset.teamVisible);if(!el.checked)draft.team.hiddenSections.push(el.dataset.teamVisible);unsaved=true;$('#revision').textContent='Cambios sin guardar';}if(el.dataset.uploadPath){const path=el.dataset.uploadPath,file=el.files[0];el.value='';if(file)withPending(()=>cropAndUpload(path,file));}if(el.dataset.reviewVisible)withPending(async()=>{try{await api('moderate',{id:el.dataset.reviewVisible,status:el.checked?'approved':'pending'});status('Visibilidad de reseña actualizada.');}catch(error){el.checked=!el.checked;throw error;}});if(el.dataset.followup)withPending(async()=>{await api('followup',{id:el.dataset.followup,status:el.value});status('Seguimiento actualizado.');});if(el.dataset.selection)withPending(async()=>{try{status(el.checked?'Cargando todas las fotos antes de agregar la propiedad…':'Retirando propiedad extra…');await api('select_property',{id:el.dataset.selection,selected:el.checked});renderCatalog(await api('catalog'));status('Selección actualizada. El catálogo público ya refleja el cambio.');}catch(error){el.checked=!el.checked;throw error;}});});
async function cropAndUpload(path,file){
 collect();status('Preparando el ajustador de imagen...');
 const crop=await openImageCropper(file||at(path),{path});if(!crop){status('Encuadre cancelado. La imagen sigue igual.');return;}
 status('Guardando la imagen ajustada...');const result=await uploadImage(crop);set(path,result.url);unsaved=true;shell();status('Encuadre listo en el borrador. Guarda y publica para mostrarlo.');
}
async function uploadImage(file){
 if(!file||file.size>3000000||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Selecciona JPG, PNG o WebP de hasta 3 MB.');
 const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});
 return api('upload',{mime:file.type,data});
}
$('#admin-panel').addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target;withPending(async()=>{
 if(form.id==='inventory-search')renderPicker(await api('inventory',{query:form.elements.query.value}));
 if(form.id==='kw-property-link')renderPicker(await api('resolve_property',{url:form.elements.url.value}));
 if(form.id==='settings-form'){const email=form.elements.email.value;if(!window.confirm('¿Enviar los próximos avisos de Confort4 a '+email+'?'))return;await api('settings',{email});state.settings.notification_email=email;status('Destinatario actualizado.');}
 if(form.id==='upload-form'){const file=await openImageCropper(form.elements.image.files[0],{path:'media'});if(!file)return;const result=await uploadImage(file);$('#upload-result').innerHTML=`<label>URL de la imagen<input readonly value="${e(result.url)}" aria-label="URL para copiar"></label><img class="upload-preview" src="${safeURL(result.url)}" alt="Imagen ajustada">`;status('Imagen ajustada lista para usar.');}
 });});
$('#login-form').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,button=$('button',form);button.disabled=true;status('Validando tu acceso…');try{const response=await fetch(endpoint,{method:'POST',headers:{apikey:config.publishableKey,Authorization:'Bearer '+config.anonKey,'Content-Type':'application/json'},body:JSON.stringify({action:'login',args:{username:form.elements.username.value,password:form.elements.password.value}}),signal:AbortSignal.timeout(20000)});const result=await response.json();if(!response.ok)throw Error(result.error||'No pudimos validar tu acceso.');session=normalizedSession(result);form.elements.password.value='';persist();await bootstrap();}catch(error){status(error.message,true);}finally{button.disabled=false;}});
let lastActivity=Date.now();
for(const event of ['pointerdown','keydown','touchstart'])window.addEventListener(event,()=>{lastActivity=Date.now();},{passive:true});
window.setInterval(()=>{if(session&&Date.now()-lastActivity>20*60*1000){const token=session.access_token;session=null;persist();localStorage.removeItem('confort4-preview');fetch(base+'/auth/v1/logout?scope=local',{method:'POST',headers:{apikey:config.publishableKey,Authorization:'Bearer '+token}}).catch(()=>{});unsaved=false;location.reload();}},30000);
if(window.top!==window.self){document.body.textContent='Abre el editor directamente en su URL.';throw Error('Embedded editor blocked');}
window.addEventListener('beforeunload',ev=>{if(unsaved){ev.preventDefault();ev.returnValue='';}});
if(session)bootstrap().catch(error=>{status(error.message,true);});
